CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(140) NOT NULL,phone VARCHAR(20) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','student','faculty','guest') NOT NULL DEFAULT 'student',department VARCHAR(100),roll_no CHAR(8) UNIQUE,semester TINYINT UNSIGNED NULL,avatar_url TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE posts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,admin_id BIGINT UNSIGNED NOT NULL,kind ENUM('photo','video','notice','pdf') NOT NULL,category VARCHAR(80) NULL,title VARCHAR(220) NOT NULL,body TEXT,media_url TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(admin_id) REFERENCES users(id));
CREATE TABLE post_reactions(post_id BIGINT UNSIGNED,user_id BIGINT UNSIGNED,PRIMARY KEY(post_id,user_id),FOREIGN KEY(post_id) REFERENCES posts(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE comments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,post_id BIGINT UNSIGNED,user_id BIGINT UNSIGNED,comment_text VARCHAR(1200),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(post_id) REFERENCES posts(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE exams(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,admin_id BIGINT UNSIGNED,title VARCHAR(220),instructions TEXT,starts_at DATETIME,ends_at DATETIME,duration_minutes INT,marks_correct DECIMAL(6,2),marks_wrong DECIMAL(6,2),status ENUM('draft','published','closed') DEFAULT 'draft',FOREIGN KEY(admin_id) REFERENCES users(id));
CREATE TABLE exam_questions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,exam_id BIGINT UNSIGNED,question_text TEXT,option_a VARCHAR(700),option_b VARCHAR(700),option_c VARCHAR(700),option_d VARCHAR(700),correct_option ENUM('A','B','C','D'),FOREIGN KEY(exam_id) REFERENCES exams(id) ON DELETE CASCADE);
CREATE TABLE exam_attempts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,exam_id BIGINT UNSIGNED,student_id BIGINT UNSIGNED,started_at DATETIME,submitted_at DATETIME,score DECIMAL(8,2),status ENUM('in_progress','submitted','auto_submitted') DEFAULT 'in_progress',UNIQUE KEY one_attempt(exam_id,student_id),FOREIGN KEY(exam_id) REFERENCES exams(id),FOREIGN KEY(student_id) REFERENCES users(id));
CREATE TABLE exam_answers(attempt_id BIGINT UNSIGNED,question_id BIGINT UNSIGNED,selected_option ENUM('A','B','C','D'),PRIMARY KEY(attempt_id,question_id),FOREIGN KEY(attempt_id) REFERENCES exam_attempts(id) ON DELETE CASCADE,FOREIGN KEY(question_id) REFERENCES exam_questions(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS feedback (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,subject VARCHAR(180) NOT NULL,message TEXT NOT NULL,is_anonymous TINYINT(1) NOT NULL DEFAULT 0,status ENUM('new','reviewed') NOT NULL DEFAULT 'new',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS direct_messages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sender_id BIGINT UNSIGNED NOT NULL,receiver_id BIGINT UNSIGNED NOT NULL,message_text TEXT NOT NULL,photo_url TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_dm_pair(sender_id,receiver_id,created_at),FOREIGN KEY(sender_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(receiver_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS admin_audit (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,actor_id BIGINT UNSIGNED NOT NULL,target_id BIGINT UNSIGNED NOT NULL,action VARCHAR(60) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(actor_id) REFERENCES users(id),FOREIGN KEY(target_id) REFERENCES users(id));

CREATE TABLE IF NOT EXISTS message_reads (
    user_id BIGINT UNSIGNED NOT NULL,
    sender_id BIGINT UNSIGNED NOT NULL,
    last_read_message_id BIGINT UNSIGNED NOT NULL DEFAULT 0,
    PRIMARY KEY (user_id, sender_id),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (sender_id) REFERENCES users(id) ON DELETE CASCADE
);
